          if (!tier || ["failed", "not-testable", "skipped"].includes(tier.status)) {
            coverage.add(`${location}/${tierName}: ${tier?.reason ?? tier?.status ?? "missing requested tier"}`);
            continue;
          }
          if (tier.status === "not-applicable") continue;
          for (const reason of tier.notTestable ?? []) coverage.add(`${location}/${tierName}: ${reason}`);
          for (const check of tier.checks ?? []) {
            if (["error", "undetermined"].includes(check.result)) coverage.add(`${location}/${tierName}/${check.name}: ${check.result}: ${check.detail}`);
            if (check.result === "fail") checks.add(`${location}/${tierName}/${check.name}: ${check.detail}`);
          }
          for (const flag of tier.flags ?? []) review.add(`${location}/${tierName}: ${flag.phrase}`);
          if (tierName === "rules") for (const engine of options.engines) {
            const result = tier.engines?.[engine];
            if (!result || result.status !== "ran") coverage.add(`${location}/${engine}: ${result?.reason ?? result?.status ?? "missing requested engine"}`);
            for (const finding of result?.incomplete ?? []) review.add(`${location}/${engine}: ${finding.ruleId}`);
          }
        }
      }
    }
  }
  /** @type {Partial<import("../types.js").PlanOptions["policy"]>} */
  const policy = options.policy ?? {};
  const status = policy.incomplete && coverage.size ? "incomplete" : failCheck?.tripped || (policy.review && review.size) || (policy.checks && checks.size) ? "failed" : "passed";
  return { status, coverage: [...coverage], review: [...review], checks: [...checks] };
}

/** @typedef {import("../types.js").ArchetypeResult} ArchetypeResult */
/** @typedef {import("../types.js").TargetResult} TargetResult */
/** @typedef {import("../types.js").EngineSummary} EngineSummary */
/** @typedef {keyof NonNullable<EngineSummary["violationsByImpact"]>} ImpactKey */

/**
 * Roll the engine results up into counts. Impact counts belong to axe and Toolkit-level counts belong to IBM.
 * @param {Record<string, ArchetypeResult>} archetypes
 * @param {string[]} engines
 * @param {string[]} [gaps]
 * @returns {TargetResult["summary"]}
 */
export function summarize(archetypes, engines, gaps = []) {
  /** @type {TargetResult["summary"]} */
  const summary = { engines: {}, gaps, notTestable: [] };
  for (const engine of engines) {
    const results = Object.values(archetypes).flatMap((a) => a.configs.map((c) => c.tiers.rules?.engines?.[engine]).filter(Boolean));
    if (results.length === 0) continue;
    const ran = results.filter((r) => r.status === "ran");
    /** @type {EngineSummary} */
    const entry = {
      status: ran.length ? "ran" : results[0].status,
      violations: ran.reduce((n, r) => n + r.violations.length, 0),
      needsReview: ran.reduce((n, r) => n + r.incomplete.length, 0),
    };
    if (engine === "axe") {
      entry.violationsByImpact = { critical: 0, serious: 0, moderate: 0, minor: 0 };
      for (const r of ran) for (const f of r.violations) if (f.impact) entry.violationsByImpact[/** @type {ImpactKey} */ (f.impact)] += 1;
    }
    if (engine === "ibm") {
      entry.violationsByToolkitLevel = { 1: 0, 2: 0, 3: 0, 4: 0 };
      for (const r of ran) for (const f of r.violations) if (f.toolkitLevel != null) entry.violationsByToolkitLevel[f.toolkitLevel] += 1;
    }
    summary.engines[engine] = entry;
  }
  for (const [name, archetype] of Object.entries(archetypes)) {
    for (const config of archetype.configs) {
      const rules = config.tiers.rules;
      if (rules?.status === "not-testable") summary.notTestable.push(`${name === "page" ? "" : `${name}: `}${rules.reason}`);
    }
  }
  const checks = Object.values(archetypes).flatMap((a) => a.configs.flatMap((c) => c.tiers.interactions?.checks ?? []));
  if (checks.length) {
    summary.interactions = { pass: 0, fail: 0, notApplicable: 0, error: 0 };
    // Interactions never report undetermined, though the shared check result type allows it.
    for (const check of checks) summary.interactions[/** @type {"pass" | "fail" | "error" | "notApplicable"} */ (check.result === "not-applicable" ? "notApplicable" : check.result)] += 1;
  }
  const measured = Object.values(archetypes).flatMap((a) => a.configs.flatMap((c) => c.tiers.computed?.checks ?? []));
  if (measured.length) {
    summary.computed = { pass: 0, fail: 0, undetermined: 0, notApplicable: 0, error: 0 };
    for (const check of measured) summary.computed[check.result === "not-applicable" ? "notApplicable" : check.result] += 1;
  }
  const adapted = Object.values(archetypes).flatMap((a) => a.configs.flatMap((c) => c.tiers.conditions?.checks ?? []));
  if (adapted.length) {
    summary.conditions = { pass: 0, fail: 0, undetermined: 0, notApplicable: 0, error: 0 };
    for (const check of adapted) summary.conditions[check.result === "not-applicable" ? "notApplicable" : check.result] += 1;
  }
  const walks = Object.entries(archetypes).flatMap(([name, a]) => a.configs.map((c) => ({ name, vsr: c.tiers.vsr })).filter((x) => x.vsr?.status === "ran"));
  if (walks.length) {
    summary.vsr = { walks: walks.length, flagged: walks.reduce((n, w) => n + w.vsr.flags.length, 0) };
    const seen = new Set();
    for (const { name, vsr } of walks) for (const entry of vsr.notTestable ?? []) {
      const line = name === "page" ? entry : `${name}: ${entry}`;
      if (!seen.has(line)) { seen.add(line); summary.notTestable.push(line); }
    }
  }
  return summary;
}

/**
 * @param {string} id
 * @param {string} reason
 * @returns {TargetResult}
 */
export function failedTarget(id, reason) {
  return { id, status: "failed", reason, archetypes: {}, summary: { engines: {}, gaps: [], notTestable: [] }, warnings: [] };
}

