/**
 * `@pantoken/ai` — consumer-facing agent assets for projects that *use* pantoken (not for
 * developing pantoken itself).
 *
 * It ships an `AGENTS.md`, an `llms.txt`, editor/agent rule files (Cursor, Copilot, Windsurf), and
 * Claude Code skills (`init-pantoken`, `create-pantoken-app`, `create-pantoken-mockup`,
 * `use-pantoken-registry`), plus
 * {@link installAgentAssets} / {@link scaffoldAndInit} / the `pantoken-ai` CLI to drop them into a
 * consumer repo at the conventional paths.
 *
 * Asset content and the writer function now live in `@pantoken/scaffold` (so the base scaffold
 * flow can offer them without a circular dependency); re-exported here for back-compat.
 *
 * @module
 * @alpha
 */
import { scaffoldProject, installAgentAssets, ASSETS, type AgentTool } from "@pantoken/scaffold";

export {
  installAgentAssets,
  AGENT_TOOLS,
  type AgentTool,
  SCAFFOLD_PLATFORMS,
  isScaffoldPlatform,
  scaffoldProject,
} from "@pantoken/scaffold";
export type { ScaffoldPlatform } from "@pantoken/scaffold";

/**
 * The `AGENTS.md` content (consumer usage guide).
 *
 * @example Serve the guide from an app route
 * ```ts
 * import { AGENTS_MD } from "@pantoken/ai";
 *
 * export function GET() {
 *   return new Response(AGENTS_MD, { headers: { "Content-Type": "text/markdown" } });
 * }
 * ```
 */
export const AGENTS_MD: string = ASSETS.agents;
/**
 * The `llms.txt` content.
 *
 * @example Write it to disk yourself
 * ```ts
 * import { writeFileSync } from "node:fs";
 * import { LLMS_TXT } from "@pantoken/ai";
 *
 * writeFileSync("llms.txt", LLMS_TXT);
 * ```
 */
export const LLMS_TXT: string = ASSETS.llms;

/**
 * Scaffold a starter project for a platform (via `@pantoken/scaffold`), and install pantoken's
 * agent assets (via {@link installAgentAssets}) into the same directory.
 *
 * @param platform - A {@link ScaffoldPlatform}.
 * @param dir - The target directory (default `"."`). Its basename (or `"pantoken-app"` for `"."`)
 *   is substituted for `{{projectName}}` in the scaffold's template files.
 * @param tool - Which agent tool's assets to install alongside the scaffold (default `"all"`).
 * @returns The paths written, scaffold files first.
 *
 * @example Scaffold a React starter with every agent asset installed
 * ```ts
 * import { scaffoldAndInit } from "@pantoken/ai";
 *
 * scaffoldAndInit("react", "./my-app");
 * ```
 */
export async function scaffoldAndInit(
  platform: string,
  dir = ".",
  tool: AgentTool | "all" = "all",
): Promise<string[]> {
  const scaffoldPaths = await scaffoldProject(platform, dir);
  const assetPaths = installAgentAssets(tool, dir);
  return [...scaffoldPaths, ...assetPaths];
}

import { findBrowser } from "../env/browser.js";

export const VIEWPORT = { width: 1280, height: 800 };

/**
 * Launch the browser we found. Playwright loads here and nowhere else, so commands that never launch a browser never pay for it.
 * @param {{ env?: NodeJS.ProcessEnv, platform?: NodeJS.Platform }} [options]
 */
export async function launchBrowser({ env, platform } = {}) {
  const { browser: found, problem } = await findBrowser({ env, platform });
  if (!found) throw new Error(problem?.message ?? "No browser found.");
  let chromium;
  try {
    ({ chromium } = await import("playwright-core"));
  } catch {
    throw new Error("playwright-core isn't installed. Run: npm install playwright-core");
  }
  const browser = await chromium.launch({ executablePath: found.path, args: process.env.CI ? ["--no-sandbox"] : [] });
  return { browser, found, version: browser.version() };
}

import { expect, test } from "vite-plus/test";
import { parseCssDocs } from "@cssdoc/core";
import { resolveExampleTargets } from "@pantoken/utils/example-targets";
import { Window } from "happy-dom";
import { COMPONENTS } from "../src/components/index.ts";
import { focus } from "../src/declarations/focus/index.ts";

const records = [...COMPONENTS, focus];

test.each(records)("authors an explicit audit example for $name", (record) => {
  const entries = parseCssDocs(record.rules("instui-"));
  const entry = entries.find((candidate) => candidate.name === record.name);
  expect(entry, record.name).toBeDefined();
  const examples = entry!.examples;
  const selected = resolveExampleTargets(examples).automatica11y;
  expect(selected.length, record.name).toBeGreaterThan(0);
  for (const index of selected) {
    const example = examples[index]!;
    const fences = [...example.matchAll(/```html[^\n]*\n([\s\S]*?)```/gu)];
    expect(fences.length, record.name).toBeGreaterThan(0);
    const window = new Window();
    window.document.body.innerHTML = fences.map((match) => match[1]).join("\n");
    expect(window.document.body.children.length, record.name).toBeGreaterThan(0);
