 * ```
 */
@scope (.pfx-tree-browser) {
  & {
    border-radius: var(--instui-component-tree-browser-border-radius);
    font-family: var(--instui-component-tree-browser-tree-collection-font-family);
    color: var(--instui-component-tree-browser-tree-button-name-text-color);
  }

  /* A collection node (a <details><summary>) and a leaf (.item) share the button chrome. */
  & details > summary,
  & .item {
    display: flex;
    align-items: center;
    gap: var(--instui-component-tree-browser-tree-button-icons-margin-right-medium);
    padding: var(--instui-component-tree-browser-tree-button-base-spacing-medium);
    font-size: var(--instui-component-tree-browser-tree-button-name-font-size-medium);
    line-height: var(--instui-component-tree-browser-tree-button-text-line-height);
    color: var(--instui-component-tree-browser-tree-button-name-text-color);
    border-radius: var(--instui-component-tree-browser-tree-button-border-radius);
    cursor: pointer;
    list-style: none;
  }

  & details > summary :is([class^="-icon-"], [class*=" -icon-"]),
  & .item :is([class^="-icon-"], [class*=" -icon-"]) {
    line-height: 1;
  }

  & details > summary::-webkit-details-marker {
    display: none;
  }

  /* The disclosure chevron rotates open (same technique as toggle-details). */
  & details > summary::before,
  & [role="treeitem"][aria-expanded] > .item::before {
    content: "";
    flex: none;
    inline-size: 1em;
    block-size: 1em;
    background: currentColor;
    -webkit-mask: var(--instui-icon-chevron-right) center / contain no-repeat;
    mask: var(--instui-icon-chevron-right) center / contain no-repeat;
    transition: transform 0.2s ease;
  }

  & details[open] > summary::before {
    transform: rotate(90deg);
  }

  & [role="treeitem"][aria-expanded="true"] > .item::before {
    transform: rotate(90deg);
  }

  & [role="treeitem"][aria-expanded] > .item:dir(rtl)::before {
    transform: rotate(180deg);
  }

  & [role="treeitem"][aria-expanded="true"] > .item:dir(rtl)::before {
    transform: rotate(90deg);
  }

  & details > summary:hover,
  & .item:hover {
    background: var(--instui-component-tree-browser-tree-button-hover-background-color);
    color: var(--instui-component-tree-browser-tree-button-hover-text-color);
  }

  & details > summary.-selected,
  & [role="treeitem"][aria-selected="true"] > .item,
  & .item[aria-selected="true"],
  & .item.-selected {
    background: var(--instui-component-tree-browser-tree-button-selected-background-color);
    color: var(--instui-component-tree-browser-tree-button-selected-text-color);
  }

  /* Nested lists indent; the leaf list carries no bullets. */
  & ul,
  & [role="group"] {
    margin: 0;
    padding-inline-start: var(--instui-component-tree-browser-tree-collection-base-spacing-medium);
    list-style: none;
  }

  &.-size-sm details > summary,
  &.-size-sm .item {
    padding: var(--instui-component-tree-browser-tree-button-base-spacing-small);
    font-size: var(--instui-component-tree-browser-tree-button-name-font-size-small);
  }

  &.-size-lg details > summary,
  &.-size-lg .item {
    padding: var(--instui-component-tree-browser-tree-button-base-spacing-large);
    font-size: var(--instui-component-tree-browser-tree-button-name-font-size-large);
  }

  @media (prefers-reduced-motion: reduce) {
    & details > summary::before,
    & [role="treeitem"][aria-expanded] > .item::before {
      transition: none;
    }
  }
}
